def _one(conn,sql,args=()):
    with conn.cursor() as cur:
        cur.execute(sql,args)
        return cur.fetchone()

def read_order(primary,replica,order_id,level,token=None,timeout=0.2,on_timeout='error'):
    if level not in ('stale','read_your_write','strong') or on_timeout not in ('error','primary'):
        raise ValueError('invalid contract')
    if type(timeout) not in (int,float) or not 0<=timeout<=1:
        raise ValueError('bounded timeout required')
    if not primary.get_autocommit() or not replica.get_autocommit() or ((primary.server_status | replica.server_status) & 1):
        raise ValueError('borrow only clean autocommit sessions')
    selected=replica;route='replica';waited=False
    if level=='strong':selected=primary;route='primary'
    elif level=='read_your_write':
        if not isinstance(token,str) or not token:raise ValueError('GTID token required')
        waited=True
        result=_one(replica,'SELECT WAIT_FOR_EXECUTED_GTID_SET(%s,%s)',(token,timeout))[0]
        if result!=0:
            if on_timeout=='error':raise TimeoutError('replica did not reach write token')
            selected=primary;route='primary'
    row=_one(selected,'SELECT amount FROM routing.orders WHERE id=%s',(order_id,))
    return {'route':route,'amount':None if row is None else str(row[0]),'waited':waited}

