import json,hashlib,os,pathlib
import task

def validate(manifest):
    if not isinstance(manifest,list) or not manifest:raise ValueError('nonempty batch required')
    ids=set()
    for r in manifest:
        if not isinstance(r,dict) or set(r)!={'request_id','order_id','level','token','timeout','on_timeout'}:raise ValueError('request schema')
        if not isinstance(r['request_id'],str) or not r['request_id'] or r['request_id'] in ids:raise ValueError('request identity')
        ids.add(r['request_id'])
        if type(r['order_id']) is not int or r['level'] not in ('stale','strong','read_your_write') or r['on_timeout'] not in ('error','primary'):raise ValueError('request contract')
        if type(r['timeout']) not in (int,float) or not 0<=r['timeout']<=1:raise ValueError('request timeout')
        if r['level']=='read_your_write':
            if not isinstance(r['token'],str) or not r['token']:raise ValueError('write token')
        elif r['token'] is not None:raise ValueError('unused token must be null')
    return hashlib.sha256(json.dumps(manifest,sort_keys=True,separators=(',',':')).encode()).hexdigest()

def run_batch(primary,replica,manifest,receipt_path,after_receipt=None):
    digest=validate(manifest)
    path=pathlib.Path(receipt_path)
    try:
        lines=path.read_text(encoding='utf-8').split('\n')
        if lines and lines[-1]=='':lines.pop()
        receipts=[json.loads(line) for line in lines]
    except FileNotFoundError:receipts=[]
    except (ValueError,UnicodeError):raise ValueError('corrupt receipt prefix')
    if len(receipts)>len(manifest):raise ValueError('receipt overflow')
    for i,row in enumerate(receipts):
        if not isinstance(row,dict) or type(row.get('index')) is not int or row.get('batch_sha256')!=digest or row.get('index')!=i or row.get('request_id')!=manifest[i]['request_id']:raise ValueError('receipt prefix conflict')
        request=manifest[i];level=request['level']
        if set(row)!={'batch_sha256','index','request_id','status','route','amount','waited'}:raise ValueError('receipt shape')
        if row['status']=='timeout':
            if level!='read_your_write' or request['on_timeout']!='error' or row['route'] is not None or row['amount'] is not None or row['waited'] is not True:raise ValueError('receipt timeout')
        elif row['status']=='ok':
            permitted=['replica'] if level=='stale' else ['primary'] if level=='strong' else ['replica','primary'] if request['on_timeout']=='primary' else ['replica']
            if row['route'] not in permitted or row['waited'] is not (level=='read_your_write'):raise ValueError('receipt route')
            if row['amount'] is not None:
                import re
                if not isinstance(row['amount'],str) or not re.fullmatch(r'-?\d+\.\d{2}',row['amount']):raise ValueError('receipt amount')
        else:raise ValueError('receipt outcome')
    # A durable prefix is evidence of earlier reads, not a promise that a read can be replayed at the same database snapshot.
    if len(receipts)==len(manifest):return receipts
    needs_separator=path.exists() and path.stat().st_size>0 and not path.read_bytes().endswith(b'\n')
    with path.open('a',encoding='utf-8',newline='\n') as out:
        if needs_separator:out.write('\n');out.flush();os.fsync(out.fileno())
        for i in range(len(receipts),len(manifest)):
            request=manifest[i]
            try:
                result=task.read_order(primary,replica,request['order_id'],request['level'],request['token'],request['timeout'],request['on_timeout'])
                row={'batch_sha256':digest,'index':i,'request_id':request['request_id'],'status':'ok',**result}
            except TimeoutError:
                row={'batch_sha256':digest,'index':i,'request_id':request['request_id'],'status':'timeout','route':None,'amount':None,'waited':True}
            out.write(json.dumps(row,sort_keys=True)+'\n');out.flush();os.fsync(out.fileno());receipts.append(row)
            if after_receipt is not None:after_receipt(i)
    return receipts

