import json,pathlib
from batch import validate

def audit(manifest,receipt_path,report_path):
    digest=validate(manifest)
    try:
        lines=pathlib.Path(receipt_path).read_text(encoding='utf-8').split('\n')
        if lines and lines[-1]=='':lines.pop()
        rows=[json.loads(line) for line in lines]
    except (ValueError,UnicodeError):raise ValueError('corrupt receipts')
    if len(rows)!=len(manifest):raise ValueError('incomplete batch')
    counts={'primary':0,'replica':0,'timeout':0};levels={level:0 for level in ('stale','strong','read_your_write')}
    for i,(request,row) in enumerate(zip(manifest,rows)):
        if not isinstance(row,dict) or type(row.get('index')) is not int or set(row)!={'batch_sha256','index','request_id','status','route','amount','waited'} or row['batch_sha256']!=digest or row['index']!=i or row['request_id']!=request['request_id']:raise ValueError('receipt identity')
        level=request['level'];levels[level]+=1
        if row['status']=='timeout':
            if level!='read_your_write' or request['on_timeout']!='error' or row['route'] is not None or row['amount'] is not None or row['waited'] is not True:raise ValueError('invalid timeout evidence')
            counts['timeout']+=1
        elif row['status']=='ok':
            permitted=['replica'] if level=='stale' else ['primary'] if level=='strong' else ['replica','primary'] if request['on_timeout']=='primary' else ['replica']
            if row['route'] not in permitted or row['waited'] is not (level=='read_your_write'):raise ValueError('route violates contract')
            if row['amount'] is not None:
                import re
                if not isinstance(row['amount'],str) or not re.fullmatch(r'-?\d+\.\d{2}',row['amount']):raise ValueError('amount evidence')
            counts[row['route']]+=1
        else:raise ValueError('unknown outcome')
    result={'batch_sha256':digest,'total':len(rows),'routes':counts,'levels':levels}
    pathlib.Path(report_path).write_text(json.dumps(result,sort_keys=True)+'\n',encoding='utf-8')
    return result

