"""Linux-only private MySQL8.4 processes, explicit GTIDs and loopback replication."""
import os,sys,pathlib,subprocess,socket,time,threading,signal,shutil,contextlib,secrets
import pymysql

LAUNCH='''import os,sys,ctypes,signal
expected=int(sys.argv[1]);libc=ctypes.CDLL(None,use_errno=True)
libc.prctl.restype=ctypes.c_int
libc.prctl.argtypes=[ctypes.c_int,ctypes.c_ulong,ctypes.c_ulong,ctypes.c_ulong,ctypes.c_ulong]
if libc.prctl(1,int(signal.SIGKILL),0,0,0)!=0 or os.getppid()!=expected:raise SystemExit(91)
os.execv(sys.argv[2],sys.argv[2:])
'''
def free_port():
 with socket.socket() as s:s.bind(('127.0.0.1',0));return s.getsockname()[1]
def execute(connection,sql,args=None):
 with connection.cursor() as cursor:cursor.execute(sql,args);return cursor.fetchall()
def scalar(connection,sql,args=None):return execute(connection,sql,args)[0][0]

class Guarded:
 def __init__(self,args,root,name,seconds=100):self.args=args;self.root=root;self.name=name;self.seconds=seconds;self.proc=None;self.thread=None;self.log=None;self.stop=threading.Event();self.error=None;self.peak=0
 def __enter__(self):
  self.log=(self.root/(self.name+'.log')).open('wb');self.proc=subprocess.Popen([sys.executable,'-B','-c',LAUNCH,str(os.getpid()),*self.args],cwd=self.root,stdout=self.log,stderr=self.log,start_new_session=True)
  started=time.monotonic()
  def watch():
   missing=0
   while not self.stop.wait(.08):
    if self.proc.poll() is not None:return
    try:
     lines=pathlib.Path('/proc/'+str(self.proc.pid)+'/status').read_text().splitlines();value=next((int(line.split()[1])*1024 for line in lines if line.startswith('VmRSS:')),None)
     if value is None:
      missing+=1
      if missing<6:continue
      raise RuntimeError('owned MySQL RSS unavailable')
     missing=0;self.peak=max(self.peak,value)
     if value>384*1048576 or time.monotonic()-started>self.seconds:raise RuntimeError('owned MySQL exceeded RSS/wall budget')
    except FileNotFoundError:return
    except Exception as error:
     if self.proc.poll() is None:self.error=str(error);os.killpg(self.proc.pid,signal.SIGKILL)
     return
  self.thread=threading.Thread(target=watch,daemon=True);self.thread.start();return self
 def __exit__(self,*args):
  self.stop.set()
  if self.proc and self.proc.poll() is None:
   os.killpg(self.proc.pid,signal.SIGTERM)
   try:self.proc.wait(5)
   except subprocess.TimeoutExpired:os.killpg(self.proc.pid,signal.SIGKILL);self.proc.wait(3)
  if self.thread:self.thread.join(1)
  if self.log:self.log.close()
  if self.error:raise AssertionError(self.error)

class Server:
 def __init__(self,root,node):self.root=pathlib.Path(root);self.node=node;self.port=free_port();self.guard=None;self.connection=None
 def __enter__(self):
