  binary=shutil.which('mysqld');assert binary,'NATIVE_ENVIRONMENT_ERROR: mysqld missing'
  version=subprocess.check_output([binary,'--no-defaults','--version'],timeout=4).decode()
  assert '8.4.' in version and 'MariaDB' not in version,'NATIVE_ENVIRONMENT_ERROR: real MySQL8.4 required'
  self.root.mkdir(parents=True,exist_ok=False);exports=self.root/'exports';exports.mkdir();base=pathlib.Path(binary).resolve().parent.parent
  args=[binary,'--no-defaults','--basedir='+str(base),'--datadir='+str(self.root/'data'),'--innodb-buffer-pool-size=64M','--performance-schema=OFF','--innodb-redo-log-capacity=16M','--innodb-log-buffer-size=4M','--innodb-doublewrite=OFF','--mysqlx=OFF','--max-connections=12','--table-open-cache=32','--table-open-cache-instances=1','--table-definition-cache=400','--thread-cache-size=0','--innodb-read-io-threads=1','--innodb-write-io-threads=1','--innodb-purge-threads=1','--tmp-table-size=1M','--max-heap-table-size=1M','--local-infile=OFF','--secure-file-priv='+str(exports),'--server-id='+str(self.node),'--gtid-mode=ON','--enforce-gtid-consistency=ON','--log-bin='+str(self.root/'binlog'),'--relay-log='+str(self.root/'relay'),'--log-replica-updates=ON','--replica-parallel-workers=1','--skip-replica-start','--binlog-expire-logs-seconds=3600']
  with Guarded(args+['--initialize-insecure','--skip-networking'],self.root,'initialize',40) as initial:
   initial.proc.wait(30);assert initial.proc.returncode==0,(self.root/'initialize.log').read_text(errors='replace')[-2500:]
  try:
   self.guard=Guarded(args+['--bind-address=127.0.0.1','--port='+str(self.port),'--socket='+str(self.root/'mysql.sock'),'--pid-file='+str(self.root/'mysql.pid'),'--max-execution-time=5000'],self.root,'server').__enter__()
   deadline=time.monotonic()+12
   while self.connection is None:
    try:self.connection=self.connect()
    except pymysql.Error:
     assert self.guard.proc.poll() is None and time.monotonic()<deadline,(self.root/'server.log').read_text(errors='replace')[-2500:]
     time.sleep(.08)
   assert int((self.root/'mysql.pid').read_text())==self.guard.proc.pid,'server escaped owned PID'
   print('NATIVE_MYSQL_GTID_SERVER_READY:'+str(self.node),flush=True);return self
  except BaseException:self.__exit__(None,None,None);raise
 def connect(self,user='root',password=''):return pymysql.connect(host='127.0.0.1',port=self.port,user=user,password=password,charset='utf8mb4',autocommit=True,connect_timeout=1,read_timeout=7,write_timeout=3,local_infile=False)
