  target=scalar(source.connection,'SELECT @@GLOBAL.gtid_executed');assert scalar(self.connection,'SELECT WAIT_FOR_EXECUTED_GTID_SET(%s,4)',(target,))==0,self.status();return target
 def __exit__(self,*args):
  if self.connection:
   try:execute(self.connection,'SHUTDOWN')
   except pymysql.Error:pass
   self.connection.close();self.connection=None
  if self.guard:self.guard.__exit__(*args);self.guard=None
  with socket.socket() as s:assert s.connect_ex(('127.0.0.1',self.port))!=0,'private MySQL port remained open'

def provision(source):
